import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { ProductsComponent } from './products.component';
import { ProductIdGuard } from '../../../core/guard/product/product-id/product-id.guard';

const routes: Routes = [
  {
    path: '',
    component: ProductsComponent
  },
  {
    path: 'id/:id',
    redirectTo: 'Id/:id',
    pathMatch: 'full'
  },
  {
    path: 'Id/:id',
    loadChildren: () => import('./product-by-id/product-by-id.module').then(m => m.ProductByIdModule),
    canActivate: [ProductIdGuard]
  },
  {
    path: 'topProducts',
    redirectTo: '/Product/TopProducts',
    pathMatch: 'full'
  },
  {
    path: 'TopProducts',
    loadChildren: () => import('./top-products/top-products.module').then(m => m.TopProductsModule)
  },
  {
    path: 'specialProducts',
    redirectTo: '/Product/SpecialProducts',
    pathMatch: 'full'
  },
  {
    path: 'SpecialProducts',
    loadChildren: () => import('./special-products/special-products.module').then(m => m.SpecialProductsModule)
  },
  {
    path: 'topViewedProducts',
    redirectTo: '/Product/TopViewedProducts',
    pathMatch: 'full'
  },
  {
    path: 'TopViewedProducts',
    // tslint:disable-next-line: max-line-length
    loadChildren: () => import('./top-viewed-products/top-viewed-products.module').then(m => m.TopViewedProductsModule)
  },
  {
    path: 'offPricedProducts',
    redirectTo: '/Product/OffPricedProducts',
    pathMatch: 'full'
  },
  {
    path: 'OffPricedProducts',
    // tslint:disable-next-line: max-line-length
    loadChildren: () => import('./off-priced-products/off-priced-products.module').then(m => m.OffPricedProductsModule)
  },
  {
    path: 'Newproducts',
    redirectTo: '/Product/NewProducts',
    pathMatch: 'full'
  },
  {
    path: 'newproducts',
    redirectTo: '/Product/NewProducts',
    pathMatch: 'full'
  },
  {
    path: 'newProducts',
    redirectTo: '/Product/NewProducts',
    pathMatch: 'full'
  },
  {
    path: 'NewProducts',
    loadChildren: () => import('../../../view/pages/product/new-products/new-products.module').then(m => m.NewProductsModule)
  },

];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ProductRoutingModule { }
